CREATE TABLE catalog_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,sku text NOT NULL,name text NOT NULL,description text NOT NULL DEFAULT '',price_cents bigint NOT NULL CHECK(price_cents>=0),currency text NOT NULL DEFAULT 'EGP',image_url text,link_url text,catalog_id text,retailer_id text,archived boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,sku));
CREATE TABLE appointment_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name text NOT NULL,duration_minutes int NOT NULL CHECK(duration_minutes BETWEEN 5 AND 1440),timezone text NOT NULL DEFAULT 'UTC',schedule jsonb NOT NULL DEFAULT '{}',calendar_connection_id uuid,calendar_id text NOT NULL DEFAULT 'primary',enabled boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,calendar_connection_id) REFERENCES integration_connections(tenant_id,id));
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,service_id uuid NOT NULL,contact_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'confirmed' CHECK(status IN('confirmed','cancelled')),event_key text NOT NULL,calendar_status text NOT NULL DEFAULT 'not_requested',calendar_error text,calendar_event_id text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,service_id) REFERENCES appointment_services(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),UNIQUE(tenant_id,event_key));
CREATE INDEX appointment_availability ON appointments(tenant_id,service_id,starts_at,ends_at) WHERE status='confirmed';
CREATE TABLE social_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,channel_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('text','image','video','carousel','cta')),body text NOT NULL,media_urls jsonb NOT NULL DEFAULT '[]',link_url text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','scheduled','sending','published','failed','ambiguous')),scheduled_at timestamptz,lease_until timestamptz,provider_id text,error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,channel_id) REFERENCES channels(tenant_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['catalog_products','appointment_services','appointments','social_posts'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t);EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO app_user',t);EXECUTE format('CREATE TRIGGER audit_commerce AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION audit_core_change()',t);END LOOP;END $$;
CREATE FUNCTION social_post_due(p_limit int) RETURNS TABLE(id uuid,tenant_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT id,tenant_id FROM social_posts WHERE(status='scheduled' AND scheduled_at<=now())OR(status='sending' AND lease_until<now()) ORDER BY scheduled_at LIMIT LEAST(p_limit,20) $$;
REVOKE ALL ON FUNCTION social_post_due(int) FROM PUBLIC;GRANT EXECUTE ON FUNCTION social_post_due(int) TO app_user;
